 if($a==='employee_sign'){$id=(int)post('waiver_id');$w=waiver($id);if(!$w||$w['status']!=='AWAITING_EMPLOYEE_SIGNATURE')throw new RuntimeException('Waiver cannot be signed.');$required=acknowledgments($w['type_code']);$given=array_values(array_unique($_POST['ack']??[]));if(count($given)!==count($required)||array_diff($required,$given)){flash('error','Check every acknowledgment.');redirect("index.php?page=new-waiver&step=5&id=$id");}if(!signature_valid(post('signature'))||!post('printed_name')){flash('error','Signature and printed name are required.');redirect("index.php?page=new-waiver&step=5&id=$id");}foreach($required as $i=>$text)run('INSERT INTO dbo.acd_mw_waiver_acknowledgments(waiver_id,acknowledgment_text,is_acknowledged,display_order,acknowledged_at) VALUES(?,?,1,?,SYSDATETIME())',[$id,$text,$i+1]);run("INSERT INTO dbo.acd_mw_waiver_signatures(waiver_id,signer_type,signer_user_id,printed_name,signature_data,ip_address,user_agent,signed_at) VALUES(?,'EMPLOYEE',?,?,?,?,?,SYSDATETIME())",[$id,user()['user_id'],post('printed_name'),post('signature'),$_SERVER['REMOTE_ADDR']??'',$_SERVER['HTTP_USER_AGENT']??'']);run("UPDATE dbo.acd_mw_waivers SET status='AWAITING_SUPERVISOR' WHERE waiver_id=?",[$id]);audit('EMPLOYEE_SIGNED','WAIVER',$id,'Employee signed');redirect("index.php?page=new-waiver&step=6&id=$id");}
